SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for visual_panel
-- ----------------------------
DROP TABLE IF EXISTS `visual_panel`;
CREATE TABLE `visual_panel`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `i18n` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '国际化code 默认使用 i18n 翻译显示名称，为空时 直接显示name',
  `type` int(4) NOT NULL COMMENT '1:Traffic Summary 2:NPM 3:DNS 4:Client IP detail 5:Domain detail  6:APP detail  7:Server IP detail',
  `params` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '默认：“” 使用json 对象保存panel 参数',
  `cby` int(10) NOT NULL COMMENT '创建人	 sys_user.id',
  `ctime` datetime(0) NOT NULL COMMENT '创建时间	',
  `uby` int(10) NOT NULL COMMENT '更新人sys_user.id',
  `utime` datetime(0) NOT NULL COMMENT '更新时间',
  `remark` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `state` int(1) NOT NULL DEFAULT 1 COMMENT '0：隐藏  1：显示  默认：1',
  `build_in` int(1) NOT NULL DEFAULT 0 COMMENT '0：非内置  1：内置  默认：0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of visual_panel
-- ----------------------------
-- ----------------------------
-- Table structure for visual_chart
-- ----------------------------
DROP TABLE IF EXISTS `visual_chart`;
CREATE TABLE `visual_chart`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `i18n` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '默认使用 i18n 翻译显示名称，为空时 直接显示name',
  `panel_id` int(10) NOT NULL COMMENT '面板id 关联visual_panel.id',
  `pid` int(10) NOT NULL DEFAULT 0 COMMENT '父节点 关联visual_chart.id 默认：0',
  `type` int(4) NOT NULL COMMENT '类型',
  `x` int(10) NOT NULL COMMENT '图表坐标',
  `y` int(10) NOT NULL COMMENT '图表坐标',
  `w` int(10) NOT NULL,
  `h` int(10) NOT NULL,
  `params` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '使用json 对象保存panel 参数 默认：“”',
  `cby` int(10) NOT NULL COMMENT '创建人	 sys_user.id',
  `ctime` datetime(0) NOT NULL COMMENT '创建时间',
  `uby` int(10) NOT NULL COMMENT '更新人sys_user.id',
  `utime` datetime(0) NOT NULL COMMENT '更新时间',
  `remark` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `state` int(1) NOT NULL DEFAULT 1 COMMENT '0：隐藏  1：显示  默认：1',
  `system` int(1) NULL DEFAULT 0 COMMENT '0：通用  1：仅主分支  2：仅六所',
  `build_in` int(1) NOT NULL DEFAULT 0 COMMENT '0：非内置  1：内置  默认：0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 651 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of visual_chart
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;